{
  "description": "The creature is a quadrupedal chimera shown in right-facing profile against a plain light background, combining the body, fur, head and paws of a brown bear with the glossy exoskeleton and horn of a large beetle. Its overall outline is bear-like and stocky, standing on four legs, but most of the dorsal surface from the back of the neck to the rump and large portions of the limbs are covered in smooth, highly reflective dark brown to black chitinous plates. A single long, curved black horn projects from the forehead. The fur is dense and brown with a lighter tan muzzle, and the paws bear long curved claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense shaggy brown fur, a lighter tan muzzle, a large black nose at the tip, small dark brown eyes, and a closed mouth, facing to the right",
      "where": "at the front end of the body, attached to the neck"
    },
    {
      "part": "horns",
      "looks_like": "single long glossy black horn, smooth and sharply curved upward and forward in a sickle shape, with two small tooth-like notches on the inner curve near the base and a pointed tip",
      "where": "emerging from the center of the forehead between the ears on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in short brown fur, with slightly darker edges",
      "where": "on top of the head on either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in long brown fur with segmented glossy dark brown chitinous armor over the upper thighs/shoulders and lower shins, the armor divided into overlapping plates with reflective highlights",
      "where": "under the body, two forelegs supporting the chest and two hindlegs supporting the rear, in a standing posture"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with brown fur on top and five long curved light tan claws protruding from the toes",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small short tuft of shaggy brown fur",
      "where": "protruding from the rear of the body beneath the posterior armored plates on the left side of the image"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark brown to black chitinous plates with smooth reflective surfaces and fine striations, including a large oval elytra-like plate covering the mid-back, smaller overlapping segmented plates covering the rear and lower back, large shoulder plates behind the neck, thigh guards on the hindquarters, and multi-segmented shin guards on all four lower legs, plus a ribbed lighter brown ventral plating with oval pits along the side of the torso",
      "where": "covering the dorsal back from neck to rump, the sides of the torso, the shoulders, and the outer and lower surfaces of all four legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
